-- pandora-primitive: pandora-forms@1.0.0
-- target: customer-app-runtime-only
DO $$ BEGIN IF to_regclass('public.project_specs') IS NOT NULL OR to_regclass('public.projectos_execution_plans') IS NOT NULL OR to_regclass('public.pandora_projects') IS NOT NULL THEN RAISE EXCEPTION 'pandora-forms customer primitive refused on Pandora Control Plane-like schema'; END IF; END $$;
CREATE TABLE IF NOT EXISTS public.primitive_forms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,form_key text NOT NULL,schema jsonb NOT NULL CHECK(jsonb_typeof(schema)='object'),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scope_id,form_key),UNIQUE(id,scope_id));
CREATE TABLE IF NOT EXISTS public.primitive_form_submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),scope_id uuid NOT NULL,form_id uuid NOT NULL,submitter_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object' AND pg_column_size(payload)<=65536),attachments jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(attachments)='array'),status text NOT NULL DEFAULT 'submitted',idempotency_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(form_id,scope_id) REFERENCES public.primitive_forms(id,scope_id) ON DELETE RESTRICT,UNIQUE(scope_id,idempotency_key));
ALTER TABLE public.primitive_forms ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_forms FORCE ROW LEVEL SECURITY;ALTER TABLE public.primitive_form_submissions ENABLE ROW LEVEL SECURITY;ALTER TABLE public.primitive_form_submissions FORCE ROW LEVEL SECURITY;REVOKE ALL ON public.primitive_forms,public.primitive_form_submissions FROM anon,authenticated;GRANT SELECT ON public.primitive_form_submissions TO authenticated;CREATE POLICY primitive_form_submissions_own_read ON public.primitive_form_submissions FOR SELECT TO authenticated USING(submitter_user_id=(SELECT auth.uid()));
-- Writes are server-side after authoritative schema/spam/attachment validation.
